using System.Diagnostics;
using System.Text.Json.Nodes;
namespace SmartTrainingPresenter;
static class Program {
    [STAThread] static int Main(string[] args){ApplicationConfiguration.Initialize();try{
        if(args.Length==3&&args[0]=="--timer-vectors"){Countdown.Vectors(args[1],args[2]);return 0;}
        if(args.Length==4&&args[0]=="--acceptance"){var form=new Trainer(args[2],true);form.Shown+=async(_,_)=>{try{await Acceptance.Run(form,args[1],args[2],args[3]);Environment.ExitCode=0;}catch(Exception ex){J.Atomic(args[3],new JsonObject{["status"]="FAIL",["error"]=ex.ToString()});Environment.ExitCode=1;}finally{form.Close();}};Application.Run(form);return Environment.ExitCode;}
        string profile=args.Length>=2&&args[0]=="--profile"?Path.GetFullPath(args[1]):ProfilePaths.Prepare();Directory.CreateDirectory(profile);
        using var sessionLock=new FileStream(Path.Combine(profile,"session.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);var trainer=new Trainer(profile);
        var recovery=Path.Combine(trainer.Profile,"Recovery.stpresenter");if(File.Exists(recovery)){var restored=new Project(recovery);var bagId=J.Str(restored.Node,"libraryBagID");var bagPath=Path.Combine(trainer.Profile,"Library/Projects",bagId+".stpresenter");if(bagId!=""&&File.Exists(bagPath))restored.Pathname=bagPath;trainer.SetProject(restored);}Application.Run(trainer);return 0;
    }catch(Exception e){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"startup-error.txt"),e.ToString());MessageBox.Show(e.ToString(),"Smart Training Presenter");return 1;}}
}
static class Acceptance {
    static void Require(bool test,string message){if(!test)throw new InvalidDataException(message);}
    public static async Task Run(Trainer f,string portable,string target,string output){var checks=new JsonArray();void Pass(string text)=>checks.Add(new JsonObject{["check"]=text,["status"]="PASS"});var watch=Stopwatch.StartNew();f.Import(portable,target);Pass("Native executable import into new isolated profile");var baseline=J.Load(Path.Combine(portable,"Library/index.json"));int items=0,approved=0,evidence=0,pdfs=0,sourcePages=0;var actualPages=new Dictionary<string,int>();
        foreach(var bag in baseline["bags"]!.AsArray()){var id=J.Str(bag!,"id");f.OpenBag(id,false);var p=f.Project!;var original=J.Load(Path.Combine(portable,"Library/Projects",id+".stpresenter"));Require(JsonNode.DeepEquals(J.Semantic(original),J.Semantic(p.Node)),"Import changed full project semantics "+id);var slides=p.Materials.FirstOrDefault(x=>J.Str(x!,"libraryRole")=="slides");if(slides!=null){await f.Render(slides,J.Int(p.Node,"currentPage"));Require(f.Preview.Frame!=null,"Slide raster was not installed");}f.Save();var reopened=Library.LoadBag(target,id);Require(JsonNode.DeepEquals(J.Semantic(original),J.Semantic(reopened.Node)),"Save/reopen changed project "+id);items+=p.Activities.Count;approved+=p.Activities.Count(x=>J.Bool(x!,"approved"));evidence+=p.Activities.Sum(x=>x!["evidence"]!.AsArray().Count);
            foreach(var m in p.Materials){var path=J.Str(m!,"path");if(!actualPages.TryGetValue(path,out var pages)){pages=await Pdf.Pages(path);actualPages[path]=pages;pdfs++;sourcePages+=pages;}Require(pages==J.Int(m!,"pages"),"Actual PDF page count differs");foreach(var e in p.Activities.SelectMany(x=>x!["evidence"]!.AsArray()).Where(e=>J.Str(e!,"fileID")==J.Str(m!,"id")))Require(J.Int(e!,"page")>=1&&J.Int(e!,"page")<=pages,"Evidence page outside PDF");}
            Pass("Open/render/save/close/reopen all fields + actual PDF pages: "+id);
        }
        var manifest=J.Load(Path.Combine(portable,"manifest.json"));Require(items==J.Int(manifest["counts"]!,"time_items")&&approved==J.Int(manifest["counts"]!,"approvals")&&evidence==J.Int(manifest["counts"]!,"evidence"),"Library totals");Pass("All IDs, links, durations, decisions and unknown fields preserved");
        // Synthetic edits are isolated from the imported library.
        var temp=Path.Combine(Path.GetDirectoryName(target)!,"cases-"+Guid.NewGuid());Directory.CreateDirectory(temp);var first=Directory.GetFiles(Path.Combine(target,"Library/Projects"),"*.stpresenter")[0];var casePath=Path.Combine(temp,"manual.stpresenter");File.Copy(first,casePath);var manual=new Project(casePath);var a=manual.Activities[0]!;var aid=J.Str(a,"id");manual.Edit(a,"duration",a["duration"]);Require(J.Bool(a,"approved"),"Same duration revoked approval");manual.Node["futureField"]=new JsonObject{["mustSurvive"]="unknown"};manual.Edit(a,"duration",JsonValue.Create(J.Num(a,"duration")+60));Require(!J.Bool(a,"approved"),"Explicit edit must clear approval");manual.Save();manual=new Project(casePath);Require(J.Str(manual.Node["futureField"]!,"mustSurvive")=="unknown","Unknown field lost");manual.Delete(aid);manual.Save();Require(!new Project(casePath).Activities.Any(x=>J.Str(x!,"id")==aid),"Deleted activity regenerated");Pass("Same-value approval retention; explicit edit; unknown fields; manual deletion roundtrip");
        bool rejected=false;try{Library.Restore(portable,target);}catch(IOException){rejected=true;}Require(rejected,"Existing profile overwritten");foreach(var path in new[]{"../escape","C:/absolute","/absolute","folder\\escape"}){rejected=false;try{J.Safe(temp,path);}catch(InvalidDataException){rejected=true;}Require(rejected,"Unsafe package path accepted");}Pass("Existing destination and path escape rejected");
        var missing=new Project(casePath);missing.Materials[0]!["path"]=Path.Combine(temp,"missing.pdf");missing.Save();Require(!File.Exists(J.Str(new Project(casePath).Materials[0]!,"path")),"Missing source test failed");var missingRoot=Path.Combine(temp,"missing-case");var missingId=J.Str(missing.Node,"libraryBagID");Directory.CreateDirectory(Path.Combine(missingRoot,"Library/Projects"));missing.Save(Path.Combine(missingRoot,"Library/Projects",missingId+".stpresenter"));rejected=false;try{Library.LoadBag(missingRoot,missingId);}catch(FileNotFoundException){rejected=true;}Require(rejected,"Application accepted missing original");Pass("Missing original rejected by application loader in isolated case");
        var export=Path.Combine(temp,"roundtrip.stbag");Library.ExportBag(f.Project!,export);var imported=Library.LoadBagPackage(export);Require(JsonNode.DeepEquals(J.Semantic(f.Project!.Snapshot()),J.Semantic(imported.Node)),"stbag semantic mismatch");Pass("stbag export/import full semantic roundtrip");
        var testCase=new Project(casePath);f.SetProject(testCase,false);var testActivity=testCase.Activities.First(x=>J.Bool(x!,"approved")&&J.Str(x!,"kind")=="نشاط")!;f.Begin(J.Str(testActivity,"id"));f.Mutate(t=>t.Pause(Clock.Now));var active=testCase.Timer(J.Str(testActivity,"id"));var before=active.Extensions;f.Proposal=1;f.Proposal--;Require(active.Extensions==before,"Proposal applied before confirmation");f.Proposal=1;f.ConfirmExtension();Require(active.Extensions==before+60&&f.Proposal==0,"Confirmed extension incorrect");Pass("Trainer +1 then -1 leaves timer unchanged; confirmation applies once");f.Search.Text="ZXQ-NO-MATCH";Require(f.Activities.Items.Count==0,"Search not filtering");f.Search.Text="";Require(f.Activities.Items.Count==testCase.Activities.Count,"Search clear failed");Pass("Search control filters and restores activity list");foreach(var set in new[]{0,1})foreach(var threshold in new[]{300,60,0}){Audio.Play(threshold,.1,set);await Task.Delay(100);}Pass("Six original sound variants sent to Windows audio API; audibility NOT TESTED");f.Save();f.OpenBag(J.Str(baseline["bags"]!.AsArray().Last()!,"id"));
        var start=Clock.Now;await Task.Delay(1200);var elapsed=Clock.Now-start;Require(elapsed>=1&&elapsed<10,"Actual Windows monotonic clock delayed observation");Pass("GetTickCount64 measured delayed scheduling against real adapter");
        var clock=new Countdown(600);clock.Toggle(Clock.Now);await Task.Delay(200);var checkpoint=clock.Checkpoint(Clock.Now);Require(!checkpoint.Running&&checkpoint.Anchor==null&&checkpoint.Elapsed>0,"Checkpoint failed");Pass("Actual adapter checkpoint resumes paused");
        f.OpenAudience();await Task.Delay(200);Require(f.Audience!=null&&f.Audience.Controls.Count==1&&f.Audience.Surface.Frame==f.Preview.Frame,"Audience separation/reuse failed");var trainerBounds=f.Bounds;f.ZoomAudience();Require(f.Bounds==trainerBounds,"Audience zoom changed trainer geometry");f.Audience!.WindowState=FormWindowState.Normal;Pass("Audience owns only slide surface; exact raster reuse; independent geometry");
        J.Atomic(output,new JsonObject{["status"]="PASS",["version"]=FileVersionInfo.GetVersionInfo(Environment.ProcessPath!).ProductVersion,["architecture"]=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(),["counts"]=manifest["counts"]!.DeepClone(),["actual_pdf_files"]=pdfs,["actual_pdf_pages"]=sourcePages,["evidence_pages_validated"]=evidence,["checks"]=checks,["screen_count"]=Screen.AllScreens.Length,["screens"]=new JsonArray(Screen.AllScreens.Select(s=>(JsonNode)new JsonObject{["name"]=s.DeviceName,["width"]=s.Bounds.Width,["height"]=s.Bounds.Height}).ToArray()),["local_render_samples"]=new JsonArray(f.RenderSamples.Select(x=>x.DeepClone()).ToArray()),["wall_seconds"]=watch.Elapsed.TotalSeconds,["not_tested"]=new JsonArray("Physical system suspend/resume","Audio heard by a human","Teams participant received image","Two physical screens if screen_count=1","PowerPoint conversion if no converter installed","Independent clean Windows machine","All manual GUI acceptance cases")});
    }
}

